    // ---------- 素材撤回与版本拉取 ----------

    @Test
    void assetWithdrawAndPullIdempotency() throws Exception {
        Ctx ctx = newContext();

        // 撤回主流程：终态且版本递增
        postJson("/api/assets/" + ctx.spliceB + "/withdraw",
